// The RPC client for browsers and Node (>= 22, or any WebSocket constructor passed in ClientOptions).
//
//   const rpc = await RpcClient.connect('ws://localhost:8080/rpc');
//   const calc = new CalcClient(rpc);                 // generated by rpcc --ts
//   const sum = await calc.compute({ op: Op.Add, a: 1, b: 2 });
//   for await (const tick of calc.count({ from: 1, to: 5 })) console.log(tick.label);
//
// One connection carries any number of concurrent calls. When the connection is lost every call fails with
// RpcError(Code.Unavailable); connect again to continue.

import { messageSize } from './bufs';
import { Envelope, Kind } from './rpc.bufs';

export enum Code {
  Ok = 0,
  Cancelled = 1,
  Unknown = 2,
  InvalidArgument = 3,
  DeadlineExceeded = 4,
  NotFound = 5,
  AlreadyExists = 6,
  PermissionDenied = 7,
  ResourceExhausted = 8,
  FailedPrecondition = 9,
  Aborted = 10,
  OutOfRange = 11,
  Unimplemented = 12,
  Internal = 13,
  Unavailable = 14,
  DataLoss = 15,
  Unauthenticated = 16,
}

export class RpcError extends Error {
  constructor(
    readonly code: Code,
    message: string,
    /** Application-defined detail of the status (0 = none). */
    readonly detail: number = 0,
  ) {
    super(message ? `${Code[code] ?? code}: ${message}` : `${Code[code] ?? code}`);
    this.name = 'RpcError';
  }
}

/** The part of the WebSocket API the client uses; the browser's and Node's WebSocket, and `ws`, fit. */
export interface WebSocketLike {
  binaryType: string;
  readonly readyState: number;
  onopen: ((event: any) => void) | null;
  onmessage: ((event: { data: any }) => void) | null;
  onclose: ((event: { code: number; reason: string }) => void) | null;
  onerror: ((event: any) => void) | null;
  send(data: ArrayBufferView | ArrayBuffer): void;
  close(code?: number, reason?: string): void;
}
export type WebSocketConstructor = new (url: string, protocols?: string | string[]) => WebSocketLike;

export interface ClientOptions {
  /** Credentials for a server whose authenticate hook reads the Hello's token. */
  token?: string;
  peer?: string;
  /** Bytes of stream items the server may send before we have consumed some. Default 1 MiB. */
  window?: number;
  /** Largest message we accept. Default 16 MiB. */
  maxMessage?: number;
  /** A ping after this much silence, so the server's idle timeout does not close the connection. Default 15 s; 0 = never. */
  pingIntervalMs?: number;
  connectTimeoutMs?: number;
  /** Default: the global WebSocket. */
  WebSocket?: WebSocketConstructor;
}

export interface CallOptions {
  /** The whole call must end within this many milliseconds. */
  timeoutMs?: number;
  signal?: AbortSignal;
}

const SUBPROTOCOL = 'librpc.v1';
const OPEN = 1;

interface Call {
  id: number;
  decode: (body: Uint8Array) => unknown;
  decodeTrailer?: (body: Uint8Array) => unknown;
  resolve?: (value: any) => void;
  reject?: (error: RpcError) => void;
  stream?: RpcStream<any, any>;
  timer?: ReturnType<typeof setTimeout>;
  cleanup?: () => void;
}

/** A server stream: `for await (const item of stream)`; break out of the loop (or cancel()) to stop it. */
export class RpcStream<T, Tr = never> implements AsyncIterable<T>, AsyncIterator<T> {
  /** The closing message of a stream whose method declares a trailer; set once the iteration has ended. */
  trailer: Tr | undefined;

  /** @internal */ items: { value: T; frameBytes: number }[] = [];
  /** @internal */ waiting?: { resolve: (r: IteratorResult<T>) => void; reject: (e: RpcError) => void };
  /** @internal */ error?: RpcError;
  /** @internal */ ended = false;

  /** @internal */
  constructor(
    private readonly client: RpcClient,
    private readonly id: number,
  ) {}

  /**
   * Client streaming and bidirectional calls: sends one item (a finished message of the method's item type), waiting
   * while the server has not read enough of what is already sent. Resolves false when the call is over (the server
   * answered, or it was cancelled): stop sending.
   */
  send(message: Uint8Array): Promise<boolean> {
    return this.client.sendItem(this.id, message);
  }

  /** Says that no more items will be sent. */
  end(): void {
    this.client.endItems(this.id);
  }

  /** Client streaming: ends the items, waits for the answer and returns it (the trailer); rejects if the call failed. */
  async finish(): Promise<Tr> {
    this.end();
    for await (const _ of this) {
      /* a client-streaming call has no items to read */
    }
    return this.trailer as Tr;
  }

  next(): Promise<IteratorResult<T>> {
    const item = this.items.shift();
    if (item) {
      this.client.consumed(item.frameBytes);
      return Promise.resolve({ value: item.value, done: false });
    }
    if (this.ended) {
      return this.error ? Promise.reject(this.error) : Promise.resolve({ value: undefined, done: true });
    }
    return new Promise((resolve, reject) => {
      this.waiting = { resolve, reject };
    });
  }

  /** Abandons the call. */
  cancel(): void {
    this.client.cancelCall(this.id, new RpcError(Code.Cancelled, 'cancelled'));
  }

  return(): Promise<IteratorResult<T>> {
    this.cancel();
    return Promise.resolve({ value: undefined, done: true });
  }

  [Symbol.asyncIterator](): AsyncIterator<T> {
    return this;
  }
}

export class RpcClient {
  private nextId = 1;
  private readonly calls = new Map<number, Call>();
  private pingTimer?: ReturnType<typeof setInterval>;
  private unreported = 0;
  private closedWith?: RpcError;
  private window = 0;
  private serverMaxMessage = 0;
  private sendUnacked = 0;
  private creditWaiters: (() => void)[] = [];

  /** The server's name and this connection's session id, from the Welcome. */
  serverName = '';
  sessionId = 0n;

  private constructor(
    private readonly ws: WebSocketLike,
    private readonly options: ClientOptions,
  ) {}

  /** Connects, says Hello and waits for the Welcome. Rejects with RpcError. */
  static connect(url: string, options: ClientOptions = {}): Promise<RpcClient> {
    const Ctor: WebSocketConstructor | undefined = options.WebSocket ?? (globalThis as any).WebSocket;
    if (!Ctor) {
      return Promise.reject(new RpcError(Code.FailedPrecondition, 'no WebSocket available; pass options.WebSocket'));
    }
    return new Promise((resolve, reject) => {
      let socket: WebSocketLike;
      try {
        socket = new Ctor(url, SUBPROTOCOL);
      } catch (e) {
        reject(new RpcError(Code.Unavailable, String(e)));
        return;
      }
      socket.binaryType = 'arraybuffer';
      const client = new RpcClient(socket, options);
      client.window = options.window ?? 1 << 20;
      const timeout = setTimeout(() => fail(new RpcError(Code.DeadlineExceeded, 'connect timed out')), options.connectTimeoutMs ?? 10000);
      let settled = false;
      const fail = (error: RpcError): void => {
        if (settled) return;
        settled = true;
        clearTimeout(timeout);
        try {
          socket.close();
        } catch {
          /* already closed */
        }
        reject(error);
      };
      socket.onerror = () => fail(new RpcError(Code.Unavailable, `cannot connect to ${url}`));
      socket.onclose = (event) => {
        if (!settled) fail(new RpcError(Code.Unavailable, `connection closed (${event.code}) ${event.reason ?? ''}`.trim()));
        else client.lost(new RpcError(Code.Unavailable, `connection closed (${event.code}) ${event.reason ?? ''}`.trim()));
      };
      socket.onopen = () => {
        socket.send(
          Envelope.encode({
            kind: Kind.Hello,
            protocol: 1,
            peer: options.peer ?? 'librpc-ts/0.1',
            token: options.token,
            window: client.window,
            maxMessage: options.maxMessage ?? 16 << 20,
          }),
        );
      };
      socket.onmessage = (event) => {
        const data = event.data as ArrayBuffer;
        if (!settled) {
          // The first frame answers the Hello.
          const env = Envelope.decode(data);
          if (env.kind === Kind.Welcome) {
            settled = true;
            clearTimeout(timeout);
            client.serverName = env.peer;
            client.sessionId = env.session;
            if (env.window) client.window = Number(env.window);
            client.serverMaxMessage = env.maxMessage;
            socket.onerror = null;
            socket.onmessage = (e) => client.onFrame(e.data as ArrayBuffer);
            client.startPings();
            resolve(client);
          } else if (env.kind === Kind.End) {
            fail(new RpcError(env.code as Code, env.message, env.detail));
          } else {
            fail(new RpcError(Code.DataLoss, 'expected Welcome'));
          }
        }
      };
    });
  }

  get connected(): boolean {
    return !this.closedWith && this.ws.readyState === OPEN;
  }

  /** Ends every running call with Unavailable and closes the connection. */
  close(): void {
    this.lost(new RpcError(Code.Unavailable, 'client closed'));
    try {
      this.ws.close(1000, 'bye');
    } catch {
      /* already closed */
    }
  }

  /** A unary call: `request` is a finished message, `decode` reads the response (e.g. `Value.decode`). */
  call<T>(method: number, request: Uint8Array, decode: (body: Uint8Array) => T, options: CallOptions = {}): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const call = this.begin(method, request, decode, options, reject);
      if (call) {
        call.resolve = resolve;
        call.reject = reject;
      }
    });
  }

  /** A server-streaming call. Errors surface from the iterator. */
  stream<T, Tr = never>(
    method: number,
    request: Uint8Array,
    decode: (body: Uint8Array) => T,
    options: CallOptions = {},
    decodeTrailer?: (body: Uint8Array) => Tr,
  ): RpcStream<T, Tr> {
    const id = this.nextId++;
    const stream = new RpcStream<T, Tr>(this, id);
    const fail = (error: RpcError): void => {
      stream.ended = true;
      stream.error = error;
    };
    const call = this.begin(method, request, decode, options, fail, id);
    if (call) {
      call.stream = stream;
      call.decodeTrailer = decodeTrailer;
    }
    return stream;
  }

  private begin(
    method: number,
    request: Uint8Array,
    decode: (body: Uint8Array) => unknown,
    options: CallOptions,
    fail: (error: RpcError) => void,
    id = this.nextId++,
  ): Call | undefined {
    if (this.closedWith) {
      fail(this.closedWith);
      return undefined;
    }
    if (options.signal?.aborted) {
      fail(new RpcError(Code.Cancelled, 'cancelled'));
      return undefined;
    }
    const envelope = Envelope.encode({ id, kind: Kind.Call, method, deadlineMs: options.timeoutMs });
    if (this.serverMaxMessage && envelope.length + request.length > this.serverMaxMessage) {
      fail(new RpcError(Code.ResourceExhausted, "request exceeds the server's maximum message size"));
      return undefined;
    }
    const frame = new Uint8Array(envelope.length + request.length);
    frame.set(envelope);
    frame.set(request, envelope.length);
    const call: Call = { id, decode };
    this.calls.set(id, call);
    if (options.timeoutMs && options.timeoutMs > 0) {
      call.timer = setTimeout(() => this.cancelCall(id, new RpcError(Code.DeadlineExceeded, 'deadline exceeded')), options.timeoutMs);
    }
    if (options.signal) {
      const onAbort = (): void => this.cancelCall(id, new RpcError(Code.Cancelled, 'cancelled'));
      options.signal.addEventListener('abort', onAbort, { once: true });
      call.cleanup = () => options.signal?.removeEventListener('abort', onAbort);
    }
    try {
      this.ws.send(frame);
    } catch (e) {
      this.finish(call, new RpcError(Code.Unavailable, String(e)));
      return undefined;
    }
    return call;
  }

  /** @internal */
  cancelCall(id: number, error: RpcError): void {
    const call = this.calls.get(id);
    if (!call) return;
    try {
      this.ws.send(Envelope.encode({ id, kind: Kind.Cancel }));
    } catch {
      /* the connection is gone anyway */
    }
    this.finish(call, error);
  }

  /** @internal */
  async sendItem(id: number, message: Uint8Array): Promise<boolean> {
    const envelope = Envelope.encode({ id, kind: Kind.Data });
    const frameBytes = envelope.length + message.length;
    if (this.serverMaxMessage && frameBytes > this.serverMaxMessage) {
      throw new RpcError(Code.ResourceExhausted, "stream item exceeds the server's maximum message size");
    }
    while (this.calls.has(id) && !this.closedWith && this.sendUnacked > 0 && this.sendUnacked + frameBytes > this.window) {
      await new Promise<void>(resolve => this.creditWaiters.push(resolve));
    }
    if (!this.calls.has(id) || this.closedWith) {
      return false;
    }
    this.sendUnacked += frameBytes;
    const frame = new Uint8Array(frameBytes);
    frame.set(envelope);
    frame.set(message, envelope.length);
    try {
      this.ws.send(frame);
    } catch {
      return false;
    }
    return true;
  }

  /** @internal */
  endItems(id: number): void {
    if (!this.calls.has(id)) return;
    try {
      this.ws.send(Envelope.encode({ id, kind: Kind.End }));
    } catch {
      /* the close handler reports it */
    }
  }

  private wakeSenders(): void {
    const waiting = this.creditWaiters;
    this.creditWaiters = [];
    for (const resolve of waiting) resolve();
  }

  /** @internal Items the caller consumed (or that were dropped): report them once a quarter window has piled up. */
  consumed(frameBytes: number): void {
    this.unreported += frameBytes;
    if (this.unreported >= Math.max(1, this.window / 4)) {
      const credit = this.unreported;
      this.unreported = 0;
      try {
        this.ws.send(Envelope.encode({ kind: Kind.Credit, credit: BigInt(credit) }));
      } catch {
        /* the close handler reports it */
      }
    }
  }

  private onFrame(data: ArrayBuffer): void {
    let env: Envelope;
    let body: Uint8Array | undefined;
    try {
      env = Envelope.decode(data);
      const size = messageSize(data);
      if (size < data.byteLength) body = new Uint8Array(data, size);
    } catch {
      this.lost(new RpcError(Code.DataLoss, 'malformed frame from server'));
      this.ws.close(1002, 'malformed frame');
      return;
    }
    switch (env.kind) {
      case Kind.Data: {
        const call = this.calls.get(env.id);
        if (!call || !call.stream || !body) {
          this.consumed(data.byteLength); // the server still counts these bytes
          return;
        }
        let value: unknown;
        try {
          value = call.decode(body);
        } catch {
          this.cancelCall(env.id, new RpcError(Code.DataLoss, 'malformed stream item'));
          return;
        }
        const stream = call.stream;
        if (stream.waiting) {
          const waiting = stream.waiting;
          stream.waiting = undefined;
          waiting.resolve({ value, done: false });
          this.consumed(data.byteLength);
        } else {
          stream.items.push({ value, frameBytes: data.byteLength });
        }
        return;
      }
      case Kind.End: {
        if (env.id === 0) {
          this.lost(new RpcError(env.code as Code, env.message, env.detail));
          return;
        }
        const call = this.calls.get(env.id);
        if (!call) return;
        if (env.code !== Code.Ok) {
          this.finish(call, new RpcError(env.code as Code, env.message, env.detail));
        } else if (call.stream) {
          if (body && call.decodeTrailer) {
            try {
              call.stream.trailer = call.decodeTrailer(body);
            } catch {
              this.finish(call, new RpcError(Code.DataLoss, 'malformed trailer'));
              return;
            }
          }
          this.finish(call);
        } else if (!body) {
          this.finish(call, new RpcError(Code.DataLoss, 'the server sent no response'));
        } else {
          try {
            this.finish(call, undefined, call.decode(body));
          } catch {
            this.finish(call, new RpcError(Code.DataLoss, 'malformed response'));
          }
        }
        return;
      }
      case Kind.Credit:
        this.sendUnacked = Math.max(0, this.sendUnacked - Number(env.credit));
        this.wakeSenders();
        return;
      case Kind.Closing:
        this.closedWith = new RpcError(Code.Unavailable, 'server is shutting down');
        return;
      default:
        return;
    }
  }

  /** Ends one call: an error, a unary result, or (neither) the clean end of a stream. */
  private finish(call: Call, error?: RpcError, value?: unknown): void {
    this.calls.delete(call.id);
    this.wakeSenders();
    if (call.timer) clearTimeout(call.timer);
    call.cleanup?.();
    if (call.stream) {
      const stream = call.stream;
      stream.ended = true;
      stream.error = error;
      if (error) {
        // what was queued is dropped; its bytes still count against the server's window
        for (const item of stream.items) this.consumed(item.frameBytes);
        stream.items = [];
      }
      if (stream.waiting) {
        const waiting = stream.waiting;
        stream.waiting = undefined;
        if (error) waiting.reject(error);
        else waiting.resolve({ value: undefined, done: true });
      }
    } else if (error) {
      call.reject?.(error);
    } else {
      call.resolve?.(value);
    }
  }

  private lost(error: RpcError): void {
    if (this.closedWith && this.closedWith.code === Code.Unavailable && this.calls.size === 0) return;
    this.closedWith ??= error;
    if (this.pingTimer) clearInterval(this.pingTimer);
    this.pingTimer = undefined;
    for (const call of [...this.calls.values()]) this.finish(call, error);
  }

  private startPings(): void {
    const every = this.options.pingIntervalMs ?? 15000;
    if (every <= 0) return;
    this.pingTimer = setInterval(() => {
      try {
        this.ws.send(Envelope.encode({ kind: Kind.Ping }));
      } catch {
        /* reported by onclose */
      }
    }, every);
    (this.pingTimer as any)?.unref?.();
  }
}

/** A client-streaming call: `send` items, then `finish()` for the answer. */
export class RpcUpload<I, R> {
  /** @internal */
  constructor(
    private readonly stream: RpcStream<never, R>,
    private readonly encode: (item: I) => Uint8Array,
  ) {}

  /** Resolves false when the call is already over (the server answered or it was cancelled): stop sending. */
  send(item: I): Promise<boolean> {
    return this.stream.send(this.encode(item));
  }

  /** Says there are no more items, waits for the answer and returns it. */
  finish(): Promise<R> {
    return this.stream.finish();
  }

  cancel(): void {
    this.stream.cancel();
  }
}

/** A bidirectional call: `send` and `end` on one side, `for await` on the other (they may run concurrently). */
export class RpcDuplex<I, O> implements AsyncIterable<O> {
  /** @internal */
  constructor(
    private readonly stream: RpcStream<O>,
    private readonly encode: (item: I) => Uint8Array,
  ) {}

  send(item: I): Promise<boolean> {
    return this.stream.send(this.encode(item));
  }

  /** No more items from this side; the server's stream goes on until it ends. */
  end(): void {
    this.stream.end();
  }

  cancel(): void {
    this.stream.cancel();
  }

  [Symbol.asyncIterator](): AsyncIterator<O> {
    return this.stream[Symbol.asyncIterator]();
  }
}
